"""Structured reconstruction of the original22-state duel scene controller.

Generated by static analysis of pinned original bytes, then maintained as named
state/phase algorithms. Runtime never reads program.json, decodes opcodes,
executes IR, or invokes an originalCPU fallback. Calls outside these local
routines require a real recovered service; missing completion remains pending.
This is one cooperative control update, not a full NES frame.
"""
from dataclasses import dataclass
import hashlib
from .battle_nmi_services import BattleNMIServices, NMIRegisters, ServiceCall
from .controller_helpers import ControlHelpers
from .duel_logic import DuelLogic,DuelTables
from .audio_services import AudioServices
from .battle_graphics_services import BattleGraphicsServices,GraphicsData

ROM_SHA256="26c8d921ff5c208191f136480bcd8d7e89c2e4ed40a0ac7b51482bcb52fe2b82"
C,Z,I,D,B,U,V,N=1,2,4,8,16,32,64,128
STATE,SUBSTATE,ACTOR=0x04A8,0x04A9,0x04AA

@dataclass(frozen=True)
class DuelSceneData:
    rules:DuelTables
    graphics:GraphicsData
    @classmethod
    def from_rom(cls,rom):
        if hashlib.sha256(rom).hexdigest()!=ROM_SHA256:raise ValueError('Pinned original ROM required')
        return cls(DuelTables.from_rom(rom),GraphicsData.from_rom(rom))

class InvalidDuelState(ValueError):pass
class SourceBudget(RuntimeError):pass

class DuelSceneController(BattleNMIServices):
    """Caller-owned real register/stack protocol with strict external services.

    services(ServiceCall)->dict must return to its actual caller PC/SP. The
    inherited pending/resume protocol records missing work without pretending
    that graphics, text, palette or input has completed. All localroutines are
    direct Python functions; routine routing is a fixed service-entry whitelist.
    """
    FIXED=()
    def __init__(self,memory,data,services=None):
        super().__init__(memory,callbacks=services)
        self.data=data if isinstance(data,DuelSceneData)else DuelSceneData.from_rom(data)
        self.logic=DuelLogic(memory,self.data.rules)
        self.audio=AudioServices(memory,self.data.graphics.audio)
        self.graphics=BattleGraphicsServices(memory,self.data.graphics)
        self.controls=ControlHelpers();self.source_locations=[];self.source_budget=100000
        self.before=None
    def _mark(self,location):
        self.registers.pc=location;self.source_locations.append(location)
        if len(self.source_locations)>self.source_budget:raise SourceBudget('Bounded source operation budget exhausted')
    def _shift(self,address,kind):
        old=self.memory[address];carry=int(bool(self.registers.p&C))
        self.flag(C,bool(old&128)if kind in ('asl','rol')else bool(old&1))
        value=(old<<1)|carry if kind=='rol'else old<<1 if kind=='asl'else (old>>1)|(carry<<7)if kind=='ror'else old>>1
        self.memory[address]=self.nz(value)
    def shift_a(self,kind):
        old=self.registers.a;carry=int(bool(self.registers.p&C))
        self.flag(C,bool(old&128)if kind in ('asl','rol')else bool(old&1))
        return self.a((old<<1)|carry if kind=='rol'else old<<1 if kind=='asl'else (old>>1)|(carry<<7)if kind=='ror'else old>>1)
    def _service(self,target,kind='tail',return_pc=None,expected_sp=None):
        r=self.registers;r.pc=target
        if target in (0xF2D7,0xE87A,0xE88A,0xE89A,0xE8AA):
            self.controls(self,target,return_pc,'tail');return
        if target in (0xE57F,0xE609,0xE683,0xE693):
            outcome=self.audio.reset(registers=r)if target==0xE57F else self.audio.request(r.a,entry=target,registers=r)
            if outcome['status']!='returned':raise RuntimeError('Real audio request did not complete')
            self.events.append(dict(kind='recovered_audio',target=target))
            self.rts();return
        if target==0xF1AD:
            outcome=self.graphics.screen_sprites(registers=r)
            if outcome['status']!='returned':raise RuntimeError('Real screenOAM constructor did not complete')
            for k,v in outcome['registers'].items():setattr(r,k,v)
            self.events.append(dict(kind='recovered_screen_OAM',target=target))
            self.rts();return
        if return_pc is None:return_pc=((self.memory[0x100+((r.sp+1)&255)]|self.memory[0x100+((r.sp+2)&255)]<<8)+1)&65535
        if expected_sp is None:expected_sp=(r.sp+2)&255
        yield ServiceCall(target,return_pc,kind,r,self.memory,tuple(getattr(self.memory,'banks',())),expected_sp)
    def call(self,pc,target,*,inline_return=None):
        caller_sp=self.registers.sp;word=(pc+2)&65535;self.push(word>>8);self.push(word)
        self.events.append(dict(kind='call',pc=pc,target=target,banks=list(getattr(self.memory,'banks',()))))
        if target in (0xF2D7,0xE87A,0xE88A,0xE89A,0xE8AA):
            self.controls(self,target,pc+3,'call')
        elif target in self.LOCAL_ENTRIES:yield from self.routine(target)
        else:yield from self._service(target,'far_call'if inline_return is not None else'call',inline_return or pc+3,caller_sp)
        expected=inline_return or((pc+3)&65535)
        if self.registers.pc!=expected or self.registers.sp!=caller_sp:
            raise RuntimeError(f'Local/service call did not return to actualcaller ${expected:04X}, SP{caller_sp:02X}')
    def _dispatch(self,pc,targets,methods):
        index=self.registers.a
        if not 0<=index<len(targets):raise InvalidDuelState(f'Dispatch at${pc:04X} index{index} outside0..{len(targets)-1}')
        word=pc+2;self.push(word>>8);self.push(word)
        self.controls(self,0xEADE,targets[index],'dispatch')
        yield from methods[index]()
    def result(self,status,**extra):
        result=super().result(status,**extra)
        result.update(before=self.before,after=[self.memory[a]for a in (STATE,SUBSTATE,ACTOR)],
                      source_operations=len(self.source_locations),full_NES_frame=False)
        return result
    def run_entry(self,entry=0xB100,*,registers=None,max_source_operations=100000):
        if entry not in self.LOCAL_ENTRIES:raise ValueError('Only proven local routine entries are allowed')
        if self._program is not None:raise RuntimeError('A real service is pending; resume before another update')
        self.before=[self.memory[a]for a in (STATE,SUBSTATE,ACTOR)];self.source_locations=[];self.source_budget=max_source_operations
        return self._start(lambda:self.routine(entry),registers,'duel_controller')
    def tick(self,registers=None,**kwargs):return self.run_entry(0xB100,registers=registers,**kwargs)


    def controller_update(self):
        """Original $B100: controller_update."""
        r=self.registers;m=self.memory
        yield from () # coroutine carrier; no service completion implied
        self._mark(0xB100)
        self.y(m[0x04AA])
        self._mark(0xB103)
        self.a(m[(0x04AB+r.y)&65535])
        self._mark(0xB106)
        if not(not(r.p&N)):
            self._mark(0xB108)
            self.a(r.y)
            self._mark(0xB109)
            self.a(r.a^0x01)
            self._mark(0xB10B)
            self.y(r.a)
            self._mark(0xB10C)
            self.a(m[(0x04AB+r.y)&65535])
        self._mark(0xB10F)
        m[0x6F44]=r.a
        self._mark(0xB112)
        self.a(m[0x04A8])
        self._mark(0xB115)
        yield from self._dispatch(0xB115,(0xB144,0xB34F,0xB5C8,0xB8C7,0xBA6D,0xBC3B,0xBCE9,0xBE78,0xC08A,0xC116,0xB144,0xB144,0xB144,0xC21C,0xC2F6,0xC464,0xC498,0xC689,0xC949,0xCB9E,0xCC87,0xCD3C,),(self.load_records_and_initialize_scene,self.alternate_actor_and_control,self.computer_action_selection,self.apply_regular_strike,self.retreat_and_pursuit,self.inspect_officer,self.surrender_result,self.persuasion_result_selection,self.verbal_abuse_status_effect,self.paired_dialogue,self.load_records_and_initialize_scene,self.load_records_and_initialize_scene,self.load_records_and_initialize_scene,self.zero_hp_animation,self.resolve_result_and_return_to_battle,self.fade_and_restart_attack_scene,self.action0_motion,self.action2_motion,self.action6_motion,self.motion_return_to_saved_state,self.motion_outward,self.motion_inward,))
        return

