    def load_records_and_initialize_scene_phase_0(self):
        """Original $B15A: 等待0087 bit7；从两条永久记录读取体力到04B1/B2，按武器ID分动画类；请求左侧精灵."""
        r=self.registers;m=self.memory
        yield from () # coroutine carrier; no service completion implied
        self._mark(0xB15A)
        self.a(m[0x0087])
        self._mark(0xB15D)
        if bool(r.p&N):
            self._mark(0xB160)
            self.inc(0x04A9)
            self._mark(0xB163)
            self.x(0x00)
            while True:
                self._mark(0xB165)
                self.a(m[(0x04AD+r.x)&65535])
                self._mark(0xB168)
                yield from self.call(0xB168,0xF2D7)
                self._mark(0xB16B)
                self.y(0x00)
                self._mark(0xB16D)
                self.a(m[(self.memory[0x00]|(self.memory[0x01]<<8))+r.y&65535])
                self._mark(0xB16F)
                m[(0x04B1+r.x)&65535]=r.a
                self._mark(0xB172)
                yield from self.call(0xB172,0xB188)
                self._mark(0xB175)
                self.x(r.x+1)
                self._mark(0xB176)
                self.cmp(r.x,0x02)
                self._mark(0xB178)
                if not(r.p&C):
                    continue
                break
            self._mark(0xB17A)
            self.a(0x43)
            self._mark(0xB17C)
            m[0x0000]=r.a
            self._mark(0xB17F)
            self.a(m[0x04AF])
            self._mark(0xB182)
            self.flag(C,False)
            self._mark(0xB183)
            self.add(0x01)
            self._mark(0xB185)
            yield from self.queue_character_background()
            return
        else:
            self._mark(0xB15F)
            self.rts()
            return

